        X.text(c, s, 100, yy - 6, { size: 13.5, w: 700, fam: S.f1, color: on ? pal[1] : X.mix(pal[0], pal[1], .5), align: "left" });
        bars(c, 100, yy + 8, 130, X.mix(pal[0], pal[1], .12), 1, 0, 4);
