          X.rr(c, px, fy + 8, w - 80, 26, 8); c.strokeStyle = i === Math.floor(X.seg(t, .2, 1.6) * 2) ? pal[2] : X.mix("#fff", pal[1], .15); c.lineWidth = 1.5; c.stroke();
