    X.text(c, "Pengguna aktif", 40, 70, { size: 11, w: 700, fam: S.f2, color: pal[2], align: "left", ls: 1.5 });
    X.text(c, cs, 38, 108, { size: 46, w: 800, fam: S.f1, color: pal[1], align: "left", ls: -1 });
    const up = X.spring(X.seg(t, 1, 1.8), 7, 5); c.save(); c.translate(48, 146); c.scale(up, up); pill(c, -10, -11, 92, 22, X.a("#22c55e", .15)); X.text(c, "\u25b2 38% bulan ini", 36, 0.5, { size: 9.5, w: 700, fam: S.f2, color: "#16a34a" }); c.restore();
