    X.text(c, S.lines[2].j, 40, 262, { size: fit(c, S.lines[2].j, 240, 15, 800, S.f1), w: 800, fam: S.f1, color: pal[1], align: "left", alpha: X.seg(t, 1.5, 2.2) });
    // logos
