    for (let i = 0; i < 7; i++) { c.save(); c.globalAlpha = .12; c.translate(X.hash(i) * W, (X.hash(i + 4) * H + t * 20 * (1 + i % 3)) % (H + 40) - 20); c.rotate(t * .5 + i); c.fillStyle = i % 2 ? pal[2] : pal[3]; X.rr(c, -14, -14, 28, 28, 8); c.fill(); c.restore(); }
