      face(c, tail, lit(front, -.25)); face(c, [[10, 14], [100, -60], [40, 4]], lit(front, .05));
      face(c, body, lit(front, .1)); face(c, [[-70, 10], [0, 30], [0, 0]], lit(front, -.18));
      face(c, neck, lit(front, .2)); face(c, head, lit(front, -.3));
