      const facingL = i % 2 === 0, col = facingL ? lit(p[1], .12 - (1 - op) * .25) : lit(darkL, -(1 - op) * .45);
      const top = y0 - (facingL ? 0 : rise), bot = y0 + ch + (facingL ? 0 : rise);
