      if (ce > .6) X.text(c, "\u2605", (A[0] + B[0] + pp[0][0]) / 3, (A[1] + B[1] + pp[0][1]) / 3, { size: sz * .26, color: p[1], alpha: X.seg(ce, .6, 1) });
